import Foundation

/// Authored training explanations. Source verification notes: docs/ContentReview.md.
/// References identify governing material, not a guarantee that an online edition is current.
enum QuestionExplanations {
    static let retiredQuestionIDs: Set<String> = ["rm-q1", "rm-q3", "roles-q6", "mishap-q1", "dorm-q3", "dorm-q6", "dorm-q110", "loto-q3", "loto-q5", "loto-q6", "loto-q10", "fall-q2", "fall-q9", "rm-q2", "rm-q6", "cs-q4", "hc-q5", "ppe-q4", "ppe-q5", "ppe-q9", "dorm-q1", "dorm-q2", "dorm-q4", "dorm-q10", "machine-guarding-q5", "fire-hot-work-q1"]

    struct Entry {
        let text: String
        let reference: QuestionReference
        var revision: Int = 1
        var afNote: String? = nil
    }
    private static let legacyEntries: [String: Entry] = [
        "loto-q1": Entry(text: "Every hazardous energy source needs effective isolation, control of stored energy, and verification before servicing. A stopped motor does not establish isolation.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(d)(3)–(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(d)(3)")!)),
        "loto-q2": Entry(text: "Maintain continuous employee protection through the shift transfer. Use the documented handover procedure; the outgoing worker must not create an unprotected interval.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(f)(4)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(f)(4)")!)),
        "loto-q103": Entry(text: "Only the applying employee normally removes a device. Employer-directed removal requires a specific trained procedure, absence verification, contact efforts, and notification before that employee resumes work.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(e)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(e)(3)")!)),
        "loto-q4": Entry(text: "Verification checks that isolation actually worked. An attempted start may be part of that check, but does not replace appropriate testing of electrical or stored-energy hazards.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(d)(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(d)(6)")!)),
        "loto-q105": Entry(text: "Host and contractor must exchange procedures and coordinate protection. Group arrangements must still protect each authorized employee; one organization's lock is not a blanket substitute.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(f)(2)–(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(f)(2)")!)),
        "loto-q106": Entry(text: "Lockout is the default for lockable devices. Tagout on a lockable device requires demonstrated equivalent protection and additional protective measures, not just a warning tag.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(c)(2)–(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(c)(2)")!)),
        "loto-q7": Entry(text: "Isolation can leave dangerous pressure or mechanical energy behind. Relieve, restrain, or otherwise render it safe, and monitor for reaccumulation when necessary.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(d)(5)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(d)(5)")!)),
        "loto-q8": Entry(text: "Authorized employees control hazardous energy for servicing. Affected employees operate the equipment or work in the affected area and must understand the purpose and restrictions of LOTO.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(b); (c)(7)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(b)")!)),
        "loto-q9": Entry(text: "The inspection checks procedure effectiveness and employee responsibilities. An authorized employee other than those using the procedure conducts it; tagout requires additional review with affected employees.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(c)(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(c)(6)")!)),
        "loto-q110": Entry(text: "Group protection must equal individual lockout. The designated coordinator tracks exposure and overall control, while personal devices protect each authorized worker throughout their work.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(f)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(f)(3)")!)),
        "fall-q1": Entry(text: "Four feet is the general-industry unprotected-edge threshold. Task-specific provisions and dangerous-equipment exposure can change what protection is required; do not transfer this number to construction automatically.", reference: QuestionReference(title: "29 CFR 1910.28", section: "(b)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.28#p-1910.28(b)(1)")!)),
        "fall-q102": Entry(text: "The standard criterion limits free fall to six feet and prevents lower-level contact. Greater free fall requires the specified demonstrated system performance; equipment instructions and clearance still govern.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(d)(2)(ii)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(d)(2)(ii)")!)),
        "fall-q3": Entry(text: "An impact-loaded system leaves service immediately. Reuse requires competent-person inspection confirming it is undamaged and safe, plus compliance with manufacturer retirement instructions.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(c)(17)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(c)(17)")!)),
        "fall-q4": Entry(text: "The normal top-edge height is 42 inches, with a three-inch tolerance. Height alone does not establish compliance; strength, openings, and the walking surface also matter.", reference: QuestionReference(title: "29 CFR 1910.29", section: "(b)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.29#p-1910.29(b)(1)")!)),
        "fall-q5": Entry(text: "Protect the worker before exposure at the roof edge. Choose a compliant system for the roof, work location, and task; an arrest system also needs clearance and rescue planning.", reference: QuestionReference(title: "29 CFR 1910.28", section: "(b)(1); (b)(13)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.28#p-1910.28(b)(1)")!)),
        "fall-q6": Entry(text: "The worker must not strike a lower level. Include deployment, deceleration, harness effects, worker dimensions, anchor geometry, and the manufacturer's clearance margin rather than lanyard length alone.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(d)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(d)(2)")!)),
        "fall-q7": Entry(text: "Competence requires identifying hazards and authority to correct them. Equipment-specific knowledge is necessary; seniority or job title alone does not establish competence.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(b), competent person; (c)(17)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(b)")!)),
        "fall-q8": Entry(text: "The total supported load includes clothing and tools. A 320-pound combined load exceeds this device's stated 310-pound rating; select a compatible system rated for the actual load.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(c), system compatibility; (d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(c)")!)),
        "fall-q109": Entry(text: "The prescriptive option is 5,000 pounds per attached employee. The alternative is a complete system designed, installed, and used under a qualified person's supervision with at least a two-to-one safety factor.", reference: QuestionReference(title: "29 CFR 1910.140", section: "(c)(13)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.140#p-1910.140(c)(13)")!)),
        "fall-q10": Entry(text: "A cover must support twice the maximum intended load and resist displacement. The appropriate protection also depends on the opening and fall exposure; a loose board is not a compliant cover.", reference: QuestionReference(title: "29 CFR 1910.29", section: "(e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.29#p-1910.29(e)")!)),
        "rm-q101": Entry(text: "DAFI 90-802 defines the 5-Step RM process: identify the hazards, assess the hazards, develop controls and make decisions, implement controls, and supervise and evaluate. Supervise and evaluate feeds back into step 1, so repeat the cycle as conditions change; completing a form does not finish risk management.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §3.2; see also DAFPAM 90-803 §2.7", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q102": Entry(text: "Authority follows applicable command policy and the residual risk. A grade or job title alone cannot establish authorization, and accepting risk is not a waiver of mandatory requirements.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.3.3, 1.6.2, 1.6.6, 3.2.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q103": Entry(text: "The DAF has two RM levels. Deliberate RM applies the formal 5-step process before a mission or activity. Real-time RM applies the same steps quickly, often as an 'on the fly' mental assessment, during execution; limited time does not justify skipping controls.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§3.1.1–3.1.2, 3.3; DAFPAM 90-803 §1.2", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q4": Entry(text: "Risk combines how severe the consequence could be with how likely it is under the stated exposure. Assess the actual task and controls rather than choosing the worst category automatically.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §3.2.2 (incl. Fig 3.3)", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q5": Entry(text: "Controls that remove or isolate hazards generally rely less on worker behavior than administrative rules and PPE. Combine controls when one measure alone cannot adequately reduce exposure.", reference: QuestionReference(title: "NIOSH Hierarchy of Controls", section: "Hierarchy of controls", url: URL(string: "https://www.cdc.gov/niosh/hierarchy-of-controls/about/index.html")!)),
        "rm-q106": Entry(text: "Changed conditions can invalidate the assessment. Pause the affected activity when protection is uncertain, reassess, and implement suitable controls before proceeding.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§3.2.3.5, 3.2.5.1.4", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q7": Entry(text: "Residual risk is what remains with the selected controls implemented. Planned but absent controls cannot be credited as though they already protect the team.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §3.2.3.2", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q8": Entry(text: "Check whether the controls actually work and remain in use. New hazards, ineffective controls, or changed conditions require another assessment and appropriate action.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §3.2.5", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q9": Entry(text: "Supervisors can accept only risk within their delegated authority. Escalate decisions above that level and document the decision as required by command policy.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.3.3, 3.2.3; Fig 3.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "rm-q10": Entry(text: "Early planning makes redesign, substitution, and resource changes possible. Waiting until execution tends to leave fewer effective options and increases dependence on behavior and PPE.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.3.4–1.3.5", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "roles-q1": Entry(text: "Commanders and directors establish the program, resources, and accountability. Safety staff advise and assess; their support does not transfer command responsibility.", reference: QuestionReference(title: "DAFI 91-202", section: "Roles and responsibilities", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q2": Entry(text: "An inspection identifies exposure, assesses compliance, and supports effective correction. Record the condition and basis for the finding rather than prescribing maximum controls without context.", reference: QuestionReference(title: "DAFI 91-202", section: "Safety inspections", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q3": Entry(text: "Protect people immediately when danger is imminent: stop the exposed activity, warn others, and notify supervision. Do not delay protective action while preparing paperwork.", reference: QuestionReference(title: "DAFI 91-202", section: "Hazard reporting and imminent danger", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q4": Entry(text: "Supervisors ensure workers receive relevant task and workplace training and retain required records. The safety office supports the program but cannot replace day-to-day supervision.", reference: QuestionReference(title: "DAFI 91-202", section: "Supervisor responsibilities and training", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q5": Entry(text: "The supervisor corrects behavior and the conditions causing misuse. Inspectors provide findings and advice; recurring problems may indicate inadequate selection, fit, availability, or training.", reference: QuestionReference(title: "DAFI 91-202", section: "Supervisor responsibilities", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q106": Entry(text: "The installation ESOHC, chaired by the installation commander, is the senior-leader governance forum for ESOH performance, trends, and open hazards (including RAC 1–3 items not corrected within 60 days). It directs corrective actions with accountable OPRs; its value is follow-through, not attendance alone.", reference: QuestionReference(title: "DAFI 90-801", section: "9 May 2024, §§2.2, 4.4; DAFI 91-202 §2.6", url: URL(string: "https://static.e-publishing.af.mil/production/1/saf_ie/publication/dafi90-801/dafi90-801.pdf")!)),
        "roles-q7": Entry(text: "Trained personnel may perform assigned tasks, but delegation does not remove supervisory accountability. The supervisor must verify the inspection and necessary corrective actions.", reference: QuestionReference(title: "DAFI 91-202", section: "Supervisor responsibilities", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q8": Entry(text: "Tracking must verify interim protection and actual correction. A closed administrative entry alone is insufficient evidence that the hazard was removed or controlled.", reference: QuestionReference(title: "DAFI 91-202", section: "Chapter 4, hazard abatement", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q9": Entry(text: "Establish effective interim protection, document the condition, and identify an accountable owner and timeline. Reassess controls while permanent correction remains outstanding.", reference: QuestionReference(title: "DAFI 91-202", section: "Chapter 4, hazard abatement", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "roles-q10": Entry(text: "Orientation must address the worker's actual tasks, exposures, emergency actions, and protection. General induction cannot substitute for task-specific qualification or training.", reference: QuestionReference(title: "DAFI 91-202", section: "Job safety training", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "cs-q1": Entry(text: "All three confined-space criteria apply. Only after identifying the space do you evaluate the atmospheric, engulfment, configuration, or other hazards that trigger permit requirements.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(b), definitions", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(b)")!)),
        "cs-q2": Entry(text: "Test oxygen, then flammable gases, then toxic contaminants. Use instruments and sampling methods appropriate to the space; acceptable oxygen alone does not establish safe entry.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(d)(5)(iii)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(d)(5)(iii)")!)),
        "cs-q3": Entry(text: "Oxygen below 19.5 percent or above 23.5 percent is hazardous under this definition. Other contaminants or physical hazards can still prohibit entry within that range.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(b), hazardous atmosphere", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(b)")!)),
        "cs-q104": Entry(text: "The attendant stays outside and performs monitoring, communication, evacuation, and rescue-summoning duties. Entry rescue requires relief and the separate training and equipment required by the rescue procedure.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(i)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(i)")!)),
        "cs-q5": Entry(text: "A prohibited condition requires terminating entry and cancelling the permit. Correct and reassess the conditions before another authorized entry; an unexpired permit is not permission to continue unsafely.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(e)(5); (j)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(e)(5)")!)),
        "cs-q6": Entry(text: "Testing and monitoring must verify that acceptable entry conditions persist. The required monitoring frequency follows hazards and the entry procedure; continuous monitoring is needed where conditions demand it.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(d)(5)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(d)(5)")!)),
        "cs-q7": Entry(text: "The entry supervisor checks permit conditions and authorizes entry. A signature is meaningful only after verifying precautions, testing, rescue arrangements, and readiness.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(b), entry supervisor; (j)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(b)")!)),
        "cs-q8": Entry(text: "Reevaluate and reclassify a space when hazards develop. Any alternative entry or later reclassification must meet its specific conditions; ventilation alone does not eliminate an atmospheric hazard.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(c)(6)–(7)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(c)(6)")!)),
        "cs-q9": Entry(text: "Evaluate rescue capability and timely availability before entry. Use non-entry retrieval unless it would increase overall risk or would not help rescue; an unevaluated emergency number is insufficient.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(k)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(k)")!)),
        "cs-q10": Entry(text: "Keep cancelled permits for at least a year to support program review. Document entry problems so the review can correct recurring deficiencies.", reference: QuestionReference(title: "29 CFR 1910.146", section: "(e)(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.146#p-1910.146(e)(6)")!)),
        "hc-q1": Entry(text: "OSHA's general-industry action level is an eight-hour TWA of 85 dBA. Your employer's program may apply additional criteria; use the applicable occupational-health assessment.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(c)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(c)")!), afNote: "Air Force: the DAF hearing conservation program (DAFI 48-127) may apply additional criteria."),
        "hc-q2": Entry(text: "An STS is an average shift of at least 10 dB at 2,000, 3,000, and 4,000 Hz in either ear relative to baseline. Apply the standard's evaluation provisions.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(g)(10)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(g)(10)")!)),
        "hc-q3": Entry(text: "Employees exposed at or above the action level need at least annual audiograms after baseline. Follow the applicable program's scheduling and follow-up requirements.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(g)(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(g)(6)")!)),
        "hc-q4": Entry(text: "A valid baseline lets later tests identify change. Required quiet periods, timing, and professional evaluation matter; an arbitrary old test is not automatically an acceptable baseline.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(g)(5)–(7)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(g)(5)")!)),
        "hc-q105": Entry(text: "Subtracting seven adjusts the NRR for A-weighted measurements. It is not a universal real-world derating rule; fit, field performance, and the applicable assessment method still matter.", reference: QuestionReference(title: "29 CFR 1910.95", section: "Appendix B", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95")!)),
        "hc-q6": Entry(text: "Written notification is due within 21 days of determining an STS. Follow-up includes appropriate protection and referral or evaluation as required, not notification alone.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(g)(8)(i)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(g)(8)(i)")!)),
        "hc-q7": Entry(text: "At 85 dBA TWA, provide hearing conservation and free protectors. Mandatory wearing has additional triggers, including lack of baseline, an STS, and exposures requiring protection under paragraph (b).", reference: QuestionReference(title: "29 CFR 1910.95", section: "(c); (i)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(c)")!)),
        "hc-q8": Entry(text: "Repeat training annually and update it for changed protection or work. Workers need to understand effects, selection and use of protection, and audiometric testing.", reference: QuestionReference(title: "29 CFR 1910.95", section: "(k)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95#p-1910.95(k)")!)),
        "hc-q9": Entry(text: "OSHA's eight-hour PEL is 90 dBA, separate from the 85 dBA action level. Other programs may set stricter limits or triggers.", reference: QuestionReference(title: "29 CFR 1910.95", section: "Table G-16", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95")!), afNote: "Air Force: do not assume the OSHA PEL is the applicable DAF exposure limit or program trigger."),
        "hc-q10": Entry(text: "The OSHA table uses a five-decibel exchange rate. Higher sound levels reduce allowed duration; other agencies and programs may use a different exchange rate.", reference: QuestionReference(title: "29 CFR 1910.95", section: "Table G-16", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.95")!)),
        "mishap-q101": Entry(text: "Class A is met by a fatality or permanent total disability, destruction of a DoD aircraft, direct mishap cost of $2,500,000 or more, or (DAF) permanent loss of a space vehicle's primary mission capability. Cost is only one path; confirm current criteria and exclusions with the safety office.", reference: QuestionReference(title: "DAFI 91-204", section: "10 March 2021, Attachment 1 (Class A Mishap); DoDI 6055.07 Glossary, thresholds per ASD memo eff. 1 Oct 2019", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q2": Entry(text: "Promptly notify the required chain using available rapid channels. Initial notification is separate from formal report deadlines; do not wait for a completed investigation.", reference: QuestionReference(title: "DAFI 91-204", section: "Mishap notification", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q3": Entry(text: "A near miss can expose a failed barrier before injury occurs. Review the contributing conditions and improve controls rather than discouraging reporting through blame.", reference: QuestionReference(title: "DAFI 91-202", section: "Hazard identification and reporting", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "mishap-q4": Entry(text: "Protect evidence after urgent rescue and hazard control. Limit unnecessary disturbance and document unavoidable changes so investigators can interpret the scene accurately.", reference: QuestionReference(title: "DAFI 91-204", section: "Evidence preservation", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q5": Entry(text: "Personal preference does not determine organizational reporting obligations. Notify the appropriate channels so qualified staff can apply recordability and reportability criteria.", reference: QuestionReference(title: "DAFI 91-204", section: "Reporting responsibilities", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q6": Entry(text: "Provide known facts, immediate protective actions, and the preliminary consequences. Distinguish confirmed information from estimates and supplement it as facts become available.", reference: QuestionReference(title: "DAFI 91-204", section: "Initial notification", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q7": Entry(text: "General criteria include medical treatment beyond first aid, loss of consciousness, days away, restriction, or job transfer. Work-relatedness, new-case criteria, and other rules must also be satisfied.", reference: QuestionReference(title: "29 CFR 1904.7", section: "(a)–(b)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1904.7#p-1904.7(a)")!)),
        "mishap-q8": Entry(text: "Reporting captures the event; investigation examines causal factors and prevention. Preserve evidence and analyze system conditions instead of stopping at a worker's last action.", reference: QuestionReference(title: "DAFI 91-204", section: "Safety investigation purpose", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-204/dafi91-204.pdf")!)),
        "mishap-q9": Entry(text: "Work-related punctures from sharps contaminated with another person's blood or other potentially infectious material are recordable. Treat them as privacy-concern cases under the applicable rules.", reference: QuestionReference(title: "29 CFR 1904.8", section: "(a)–(b)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1904.8#p-1904.8(a)")!)),
        "mishap-q10": Entry(text: "Patterns help target controls, training, and resources. Consider exposure and reporting changes before assuming a higher raw count proves worsening safety performance.", reference: QuestionReference(title: "DAFI 91-202", section: "Mishap prevention program evaluation", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "ppe-q1": Entry(text: "PPE reduces exposure at the worker but does not remove the hazard. Assess higher-level controls first and use suitable PPE for remaining exposure.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(a); (d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(a)")!)),
        "ppe-q2": Entry(text: "Assess the workplace, select suitable protection, communicate the selection, and ensure fit. Document the assessment as required; a generic equipment list is insufficient.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(d)")!)),
        "ppe-q3": Entry(text: "Eye protection must address both impact and chemical splash. A face shield supplements suitable eye protection when the assessment calls for it; it is not an automatic substitute for goggles.", reference: QuestionReference(title: "29 CFR 1910.133", section: "(a)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.133#p-1910.133(a)")!)),
        "ppe-q104": Entry(text: "Required PPE is generally employer-paid, but the rule contains specific exceptions. Verify the item and its use instead of applying an absolute payment rule.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(h)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(h)")!)),
        "ppe-q105": Entry(text: "APF is only one selection factor. Verify the contaminant, concentration, oxygen and IDLH conditions, approved configuration, service life, and fit before deciding whether a respirator is suitable.", reference: QuestionReference(title: "29 CFR 1910.134", section: "(d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.134#p-1910.134(d)")!)),
        "ppe-q6": Entry(text: "Training covers selection, use, limitations, and care. Workers must demonstrate understanding and ability before performing work requiring PPE; repeat training when needed.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(f)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(f)")!)),
        "ppe-q7": Entry(text: "Select gloves for the task, duration, conditions, and hazards. Dexterity matters, but a thinner glove is acceptable only if its protective performance remains suitable.", reference: QuestionReference(title: "29 CFR 1910.138", section: "(b)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.138#p-1910.138(b)")!)),
        "ppe-q8": Entry(text: "Protection must remain in reliable condition. Check before use and follow equipment-specific inspection requirements; damaged or defective PPE must not be used.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(a); (e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(a)")!)),
        "ppe-q109": Entry(text: "Required tight-fitting respirators need medical evaluation, appropriate fit testing, and training before use. Loose-fitting respirators do not use the same fit-test requirement.", reference: QuestionReference(title: "29 CFR 1910.134", section: "(e); (f); (k)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.134#p-1910.134(e)")!)),
        "ppe-q10": Entry(text: "Damaged PPE cannot provide reliable protection. Remove it from use and provide suitable replacement or approved repair before the worker is exposed.", reference: QuestionReference(title: "29 CFR 1910.132", section: "(e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.132#p-1910.132(e)")!)),
        "dorm-q101": Entry(text: "Safety staff assess and recommend controls; the appropriate authority makes risk decisions. RM does not absolve compliance: a risk memorandum cannot waive a mandatory requirement. Noncompliance needs a waiver, variance, or exemption through the proper authority, with interim controls in place.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.6.2, 1.6.6; DAFI 91-202 §1.5.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "dorm-q102": Entry(text: "Use the applicable command policy, mission context, and residual risk to identify authority. Do not teach one rank as a universal authorization for all deployments.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.3.3, 2.6.6, 3.2.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "dorm-q103": Entry(text: "On contract work, safety personnel report violations to the contracting officer or COR. For critical or imminent danger, DAFI 91-202 directs safety personnel to act to stop the operation and immediately contact the contracting officer. Host-nation labor terms do not remove that duty, but an inspector still cannot unilaterally rewrite the contract.", reference: QuestionReference(title: "DAFI 91-202", section: "20 March 2020 (Chg 1, 10 Apr 2024), §§12.4.7–12.4.8; 3.13.2–3.13.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "dorm-q104": Entry(text: "Remove people from suspected exhaust exposure first; shut down the source only if safe. CO itself has no odor. Assess air and equipment placement before allowing reoccupation or reuse.", reference: QuestionReference(title: "OSHA Portable Generator Safety", section: "Carbon monoxide exposure response", url: URL(string: "https://www.osha.gov/sites/default/files/publications/OSHA4105.pdf")!)),
        "dorm-q5": Entry(text: "Bypassing protection creates an uncontrolled electrical hazard. Use a safe alternative and qualified personnel; qualification depends on the equipment and task, not just an occupational label.", reference: QuestionReference(title: "29 CFR 1910.333", section: "(a); (c)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.333#p-1910.333(a)")!)),
        "dorm-q106": Entry(text: "During execution, RTRM applies the 5-step process quickly to changing conditions. Fatigue, poor visibility, and route hazards interact; controls can include delay or a safer alternative, and significant plan changes may need higher approval. Urgency does not make proceeding obligatory.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§3.1.2, 3.3 (3.3.5); DAFPAM 90-803 §1.2.2, Ch 8", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "dorm-q7": Entry(text: "Inspectors supply hazard analysis and control recommendations. Residual-risk decisions belong to the authority designated by the applicable command policy.", reference: QuestionReference(title: "DAFI 90-802", section: "20 January 2026, §§1.3.3, 3.2.3", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi90-802/dafi90-802.pdf")!)),
        "dorm-q8": Entry(text: "Prompt interim controls protect people while permanent correction is arranged. Assign responsibility and verify effectiveness; documentation without protection is not adequate abatement.", reference: QuestionReference(title: "DAFI 91-202", section: "Chapter 4, hazard abatement", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "dorm-q9": Entry(text: "Deployment does not remove the need for accessible reporting and follow-up. Use available channels and act promptly on imminent hazards while formal documentation follows.", reference: QuestionReference(title: "DAFI 91-202", section: "Chapter 4, hazard reporting", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafi91-202/dafi91-202.pdf")!)),
        "dorm-q210": Entry(text: "DAFMAN 91-203 directs use of the guidance that provides the most protection for the employee until the conflict is resolved. Report conflicts through the MAJCOM/FLDCOM occupational safety office to HQ AFSEC/SEGS; host-nation conflicts go up the chain for resolution. Signing a risk-acceptance letter does not resolve the conflict.", reference: QuestionReference(title: "DAFMAN 91-203", section: "24 February 2026, §§1.4.2, 1.5; opening paragraph (conflict reporting)", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafman91-203/dafman91-203.pdf")!)),
        "hazcom-q1": Entry(text: "HazCom links hazard classification to usable information through labels, safety data sheets, and training. Merely possessing SDS files does not complete the program.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(a)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(a)")!)),
        "hazcom-q2": Entry(text: "Workplace containers need identity and hazard information. The immediate-use exception applies to the employee who made the transfer within that work shift, not to shared storage bottles.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(f)(6); (f)(8)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(f)(6)")!)),
        "hazcom-q3": Entry(text: "Train at initial assignment and when a new chemical hazard enters the work area. A new product does not necessarily mean a new hazard, but training must cover the actual exposure.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(h)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(h)(1)")!)),
        "hazcom-q4": Entry(text: "Workers need immediate access during their shifts. Electronic access is acceptable only when it creates no barrier to obtaining the information promptly.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(g)(8)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(g)(8)")!)),
        "hazcom-q5": Entry(text: "Do not expose workers to an unidentified chemical without required hazard information. Secure it and obtain the correct labeling and SDS through the responsible supplier or program channels.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(f); (g)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(f)")!)),
        "hazcom-q6": Entry(text: "The written program explains how labeling, SDSs, and training work, including non-routine tasks and multi-employer communication. It must describe actual workplace arrangements.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(e)")!)),
        "hazcom-q7": Entry(text: "Shipped hazardous-chemical containers require the applicable standardized label elements and supplier information. Workplace alternatives are governed by separate provisions.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(f)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(f)(1)")!)),
        "hazcom-q8": Entry(text: "A non-routine task can change exposure conditions. Explain the chemical hazards and protective procedures before the task, including emergency actions and isolation needs.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(e)(1)(ii); (h)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(e)(1)(ii)")!)),
        "hazcom-q9": Entry(text: "The broad hazard class does not establish compatibility. Use chemical-specific handling, storage, stability, and reactivity information to determine suitable separation.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "Appendix D, sections 7 and 10", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200")!)),
        "hazcom-q10": Entry(text: "Training must leave workers able to recognize hazards and use protective measures. Resolve gaps in comprehension and verify understanding, rather than relying on attendance records alone.", reference: QuestionReference(title: "29 CFR 1910.1200", section: "(h)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.1200#p-1910.1200(h)")!)),
        "electrical-q1": Entry(text: "Guard live parts at 50 volts or more using an accepted method. An opening that permits accidental contact defeats the enclosure even when warning labels are present.", reference: QuestionReference(title: "29 CFR 1910.303", section: "(g)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.303#p-1910.303(g)(2)")!)),
        "electrical-q2": Entry(text: "Working clearance depends on voltage and facing conditions. Storage cannot occupy required space; use the applicable table and equipment configuration rather than a universal clearance guess.", reference: QuestionReference(title: "29 CFR 1910.303", section: "(g)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.303#p-1910.303(g)(1)")!)),
        "electrical-q3": Entry(text: "Flexible cords cannot replace fixed wiring or pass through wall openings as described. Have the installation corrected using an approved permanent wiring method.", reference: QuestionReference(title: "29 CFR 1910.305", section: "(g)(1)(iv)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.305#p-1910.305(g)(1)(iv)")!)),
        "electrical-q4": Entry(text: "Damaged portable equipment leaves service until repairs and tests establish safety. Tape over exposed conductors is not a substitute for a suitable repair.", reference: QuestionReference(title: "29 CFR 1910.334", section: "(a)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.334#p-1910.334(a)(2)")!)),
        "electrical-q5": Entry(text: "De-energize exposed parts before work unless a specified exception applies. Isolate, lock or tag as required, and have a qualified person verify absence of voltage.", reference: QuestionReference(title: "29 CFR 1910.333", section: "(a)(1); (b)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.333#p-1910.333(a)(1)")!)),
        "electrical-q6": Entry(text: "Qualification requires relevant training and knowledge of the specific hazards and practices. Being qualified on one system does not automatically qualify a person on every installation.", reference: QuestionReference(title: "29 CFR 1910.332", section: "(b)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.332#p-1910.332(b)(3)")!)),
        "electrical-q7": Entry(text: "Boxes need suitable covers to prevent contact and contain the installation. Correct the exposure using safe work practices before restoring normal access.", reference: QuestionReference(title: "29 CFR 1910.305", section: "(b)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.305#p-1910.305(b)(2)")!)),
        "electrical-q8": Entry(text: "Use listed equipment according to its listing and instructions. Connecting power strips together can defeat their intended supply arrangement and overload components.", reference: QuestionReference(title: "29 CFR 1910.303", section: "(b)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.303#p-1910.303(b)(2)")!)),
        "electrical-q9": Entry(text: "A GFCI detects current imbalance and interrupts the circuit rapidly. It supplements safe equipment and practices; it does not protect against every possible electrical contact.", reference: QuestionReference(title: "29 CFR 1910.304", section: "(b)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.304#p-1910.304(b)(3)")!)),
        "electrical-q10": Entry(text: "Disconnects must identify their purpose unless it is evident. Clear durable identification helps prevent isolation of the wrong circuit during work or emergencies.", reference: QuestionReference(title: "29 CFR 1910.303", section: "(f)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.303#p-1910.303(f)")!)),
        "machine-guarding-q1": Entry(text: "Guard the hazards workers can reach, including operation points and moving parts. The correct guard depends on the machine and exposure, not merely whether a guard is installed somewhere.", reference: QuestionReference(title: "29 CFR 1910.212", section: "(a)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.212#p-1910.212(a)(1)")!)),
        "machine-guarding-q2": Entry(text: "Production pressure does not remove point-of-operation protection requirements. Prevent exposure until an effective compliant safeguard is restored.", reference: QuestionReference(title: "29 CFR 1910.212", section: "(a)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.212#p-1910.212(a)(3)")!)),
        "machine-guarding-q3": Entry(text: "Keep the adjustable upper tongue guard within one-quarter inch of the wheel. Recheck as the wheel wears; this is separate from the work-rest gap.", reference: QuestionReference(title: "29 CFR 1910.215", section: "(b)(9)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.215#p-1910.215(b)(9)")!)),
        "machine-guarding-q4": Entry(text: "Keep the work rest within one-eighth inch to prevent work from becoming wedged. Adjust and secure it with the wheel stopped.", reference: QuestionReference(title: "29 CFR 1910.215", section: "(a)(4)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.215#p-1910.215(a)(4)")!)),
        "machine-guarding-q105": Entry(text: "Inspection and an appropriate sound test can reveal damage before mounting. Wheel type affects whether a ring test is meaningful; follow the applicable test and manufacturer instructions.", reference: QuestionReference(title: "29 CFR 1910.215", section: "(d)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.215#p-1910.215(d)(1)")!)),
        "machine-guarding-q6": Entry(text: "Projecting fasteners can snag clothing and pull a worker into rotating parts. Use permitted flush, countersunk, covered, or guarded arrangements to prevent contact.", reference: QuestionReference(title: "29 CFR 1910.219", section: "(h)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.219#p-1910.219(h)(1)")!)),
        "machine-guarding-q7": Entry(text: "An emergency stop acts after someone activates it; a guard prevents exposure. A stop button cannot replace required safeguarding.", reference: QuestionReference(title: "29 CFR 1910.212", section: "(a)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.212#p-1910.212(a)")!)),
        "machine-guarding-q8": Entry(text: "Jam clearing can expose a worker to unexpected movement or stored energy. Apply required energy control; any minor-servicing exception must meet all its conditions and provide effective alternative protection.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(a)(2); (d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(a)(2)")!)),
        "machine-guarding-q9": Entry(text: "A safeguard must prevent hazardous contact without creating another hazard. Secure mounting and suitability for the actual operation matter more than appearance alone.", reference: QuestionReference(title: "29 CFR 1910.212", section: "(a)(2)–(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.212#p-1910.212(a)(2)")!)),
        "machine-guarding-q10": Entry(text: "Before restoring energy, check equipment integrity, remove nonessential items, position people safely, and notify affected employees. Restore guarding before normal operation.", reference: QuestionReference(title: "29 CFR 1910.147", section: "(e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.147#p-1910.147(e)")!)),
        "material-handling-q1": Entry(text: "Clear, suitably marked passageways support safe equipment and pedestrian movement. Temporary storage must not compromise required aisle clearance or safe access.", reference: QuestionReference(title: "29 CFR 1910.176", section: "(a)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.176#p-1910.176(a)")!)),
        "material-handling-q2": Entry(text: "Stacks must resist sliding and collapse. Assess the load, support, height, and arrangement rather than treating the available ceiling height as the storage limit.", reference: QuestionReference(title: "29 CFR 1910.176", section: "(b)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.176#p-1910.176(b)")!)),
        "material-handling-q3": Entry(text: "An unsafe truck leaves service until restored to safe condition. Reducing speed is not an acceptable workaround for failed brakes.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(p)(1); (q)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(p)(1)")!)),
        "material-handling-q4": Entry(text: "Evaluate performance at least every three years. Unsafe operation, incidents, assignment changes, and changed conditions can trigger refresher training sooner.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(l)(4)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(l)(4)")!)),
        "material-handling-q5": Entry(text: "Capacity and configuration markings must remain present and legible. Operators cannot safely substitute an estimate for the truck's verified rated capacity.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(a)(6)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(a)(6)")!)),
        "material-handling-q6": Entry(text: "Travel with a stable load, safe clearance, and a clear view in the direction of travel. Follow truck instructions and site conditions, including reversing when a load blocks forward vision.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(n); (o)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(n)")!)),
        "material-handling-q7": Entry(text: "Changes affecting capacity or safe operation need prior written manufacturer approval. Update required markings so operators can identify the resulting capacity and configuration.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(a)(4)–(5)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(a)(4)")!)),
        "material-handling-q8": Entry(text: "People must not stand or pass beneath elevated truck portions, whether loaded or empty. An apparently stable load does not remove this exclusion.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(m)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(m)(2)")!)),
        "material-handling-q9": Entry(text: "Inspect lifting gear before use and remove defective items. Match identification, capacity, hitch, and condition to the lift; the sling rating alone does not validate the entire lifting arrangement.", reference: QuestionReference(title: "29 CFR 1910.184", section: "(d); (e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.184#p-1910.184(d)")!)),
        "material-handling-q10": Entry(text: "A pallet is not a personnel platform. Use equipment intended and approved for lifting people, with required guarding, secure attachment, operating controls, and applicable site authorization.", reference: QuestionReference(title: "29 CFR 1910.178", section: "(a)(2); (m)(12)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.178#p-1910.178(a)(2)")!)),
        "fire-hot-work-q101": Entry(text: "OSHA's fire-watch minimum is 30 minutes after covered hot work. Applicable fire-code, permit, or local requirements may be longer; do not assume the OSHA minimum completes every permit.", reference: QuestionReference(title: "29 CFR 1910.252", section: "(a)(2)(iii)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.252#p-1910.252(a)(2)(iii)")!), afNote: "Air Force: DAF and local F&ES requirements may require a longer fire watch."),
        "fire-hot-work-q2": Entry(text: "The authorizing person checks the area and needed precautions before work. The permit documents authorization and controls; it does not itself make unsafe conditions acceptable.", reference: QuestionReference(title: "29 CFR 1910.252", section: "(a)(2)(iv)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.252#p-1910.252(a)(2)(iv)")!)),
        "fire-hot-work-q3": Entry(text: "Extinguishers must be accessible without exposing workers to injury. Restore access and correct storage practices so the obstruction does not recur.", reference: QuestionReference(title: "29 CFR 1910.157", section: "(c)(1)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.157#p-1910.157(c)(1)")!)),
        "fire-hot-work-q4": Entry(text: "Annual maintenance is separate from the monthly visual inspection. Retain the required maintenance date record and address defects when discovered.", reference: QuestionReference(title: "29 CFR 1910.157", section: "(e)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.157#p-1910.157(e)")!)),
        "fire-hot-work-q5": Entry(text: "Exit routes must stay free and unobstructed. Even temporary equipment or storage can delay escape and reduce the available route width.", reference: QuestionReference(title: "29 CFR 1910.37", section: "(a)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.37#p-1910.37(a)(3)")!)),
        "fire-hot-work-q6": Entry(text: "Previously used containers can retain explosive or toxic residues. Clean and prepare them using an appropriate procedure; never infer safety from emptiness or lack of odor.", reference: QuestionReference(title: "29 CFR 1910.252", section: "(a)(3)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.252#p-1910.252(a)(3)")!)),
        "fire-hot-work-q7": Entry(text: "Stored oxygen normally needs 20 feet separation from fuel gas or combustibles, or a noncombustible barrier at least five feet high with a half-hour fire-resistance rating.", reference: QuestionReference(title: "29 CFR 1910.253", section: "(b)(4)(iii)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.253#p-1910.253(b)(4)(iii)")!)),
        "fire-hot-work-q8": Entry(text: "Sparks can ignite concealed or adjacent combustibles through openings. Inspect and protect those areas before work; if hazards cannot be controlled, do not proceed there.", reference: QuestionReference(title: "29 CFR 1910.252", section: "(a)(2)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.252#p-1910.252(a)(2)")!)),
        "fire-hot-work-q9": Entry(text: "Check liquid category, quantity limits, compatible containers, and cabinet use. An approved cabinet does not make unlimited or incompatible storage acceptable.", reference: QuestionReference(title: "29 CFR 1910.106", section: "(d)", url: URL(string: "https://www.ecfr.gov/current/title-29/section-1910.106#p-1910.106(d)")!)),
        "fire-hot-work-q10": Entry(text: "Coordinate with the designated permit-authorizing and fire-prevention officials. Apply current DAF and local fire requirements before work, including any extended fire-watch requirement.", reference: QuestionReference(title: "DAFMAN 91-203", section: "24 February 2026, §§20.8.1–20.8.1.4.3; 20.10", url: URL(string: "https://static.e-publishing.af.mil/production/1/af_se/publication/dafman91-203/dafman91-203.pdf")!)),
    ]
    static let entries: [String: Entry] = legacyEntries.merging(OSHAExpansion.entries) { _, new in new }
}
